import json
dados = json.load(open('/workspace/.latest_query.json'))
linhas = dados if isinstance(dados, list) else dados.get('registros', dados.get('dados', []))
def norm(n):
    import unicodedata
    return unicodedata.normalize('NFKD', n).encode('ascii','ignore').decode().upper().replace(' - ',' ')
from collections import defaultdict
d = defaultdict(list)
for r in linhas:
    d[r['nome_do_campus']].append(norm(r['nome_da_unidade']))
cg = set(d['CAMPINA GRANDE'])
outros = set()
for c,us in d.items():
    if c != 'CAMPINA GRANDE': outros.update(us)
print('EXCLUSIVAS DE CAMPINA GRANDE:')
for u in sorted(d['CAMPINA GRANDE']):
    if u not in outros: print(' -', u)
print()
print('COMPARTILHADAS (nome igual em outro campus):')
for u in sorted(d['CAMPINA GRANDE']):
    if u in outros: print(' -', u)
